const code = `import fs from 'node:fs';
const html = fs.readFileSync(process.argv[2],'utf8');
const cards = html.split('bili-video-card__wrap').slice(1);
const out=[];
for (const c of cards){
  const sub = c.substring(0, 6000);
  const titleM = sub.match(/title="([^"]{4,120})"/);
  const hrefM = sub.match(/href="(\\/\\/www\\.bilibili\\.com\\/video\\/[^"]+)"/);
  const authorM = sub.match(/class="bili-video-card__info--author"[^>]*>([^<]*)</);
  const dateM = sub.match(/class="bili-video-card__info--date"[^>]*>·\\s*([^<]*)</);
  const stats = [...sub.matchAll(/class="bili-video-card__stats--item"[^>]*>[\\s\\S]{0,300}?<span[^>]*>([0-9.]+[万]?)<\\/span>/g)].map(m=>m[1]);
  if(titleM) out.push({title:titleM[1], views:stats[0]||'', danmaku:stats[1]||'', author:authorM?authorM[1].trim():'', date:dateM?dateM[1].trim():''});
}
console.log(JSON.stringify(out.slice(0,25),null,1));
console.error('cards='+cards.length+' parsed='+out.length);
`;
await tools.write({ file_path: "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts\\_b_bili_parse.mjs", content: code });
const r = await tools.pwsh({
  description: "Parse bilibili search cards",
  command: `cd "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts"
node _b_bili_parse.mjs _b_bili_fuye.html 2>&1 | Select-Object -First 120
`,
  timeoutMs: 60000
});
console.log(r.kind === "foreground" ? r.stdout.text + "\nERR:" + r.stderr.text : JSON.stringify(r));
